/* ============================================================
   GREEN ZONE — tiny WebAudio synth
   No assets, no dependencies. All sounds are generated.
   ============================================================ */
(function () {
  'use strict';

  class Sfx {
    constructor() {
      this.ctx = null;
      this.master = null;
      this.musicGain = null;
      this.musicNodes = null;
      this.noise = null;
      this.muted = localStorage.getItem('gz.muted') === '1';
      this.lastShot = 0;
    }

    get supported() {
      return !!(window.AudioContext || window.webkitAudioContext);
    }

    init() {
      if (!this.supported) return false;
      if (!this.ctx) {
        const Ctx = window.AudioContext || window.webkitAudioContext;
        this.ctx = new Ctx();
        this.master = this.ctx.createGain();
        this.master.gain.value = this.muted ? 0 : 0.7;
        this.master.connect(this.ctx.destination);
        this.noise = this.makeNoise();
      }
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return true;
    }

    makeNoise() {
      const ctx = this.ctx;
      const buf = ctx.createBuffer(1, ctx.sampleRate * 1.2, ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
      return buf;
    }

    setMuted(muted) {
      this.muted = muted;
      localStorage.setItem('gz.muted', muted ? '1' : '0');
      if (this.master && this.ctx) {
        this.master.gain.cancelScheduledValues(this.ctx.currentTime);
        this.master.gain.setTargetAtTime(muted ? 0 : 0.7, this.ctx.currentTime, 0.03);
      }
      if (muted) this.stopMusic();
    }

    now() { return this.ctx ? this.ctx.currentTime : 0; }

    tone({ type = 'sine', f0 = 440, f1 = f0, dur = 0.15, vol = 0.2, delay = 0, attack = 0.005, curve = 'exp' }) {
      if (!this.ctx || this.muted) return;
      const t = this.now() + delay;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(Math.max(20, f0), t);
      if (curve === 'exp') osc.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
      else osc.frequency.linearRampToValueAtTime(Math.max(20, f1), t + dur);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(vol, t + attack);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(gain).connect(this.master);
      osc.start(t);
      osc.stop(t + dur + 0.02);
    }

    burst({ dur = 0.25, vol = 0.25, f0 = 1600, f1 = 120, q = 1.1, delay = 0, type = 'lowpass' }) {
      if (!this.ctx || this.muted) return;
      const t = this.now() + delay;
      const src = this.ctx.createBufferSource();
      src.buffer = this.noise;
      const filter = this.ctx.createBiquadFilter();
      filter.type = type;
      filter.Q.value = q;
      filter.frequency.setValueAtTime(f0, t);
      filter.frequency.exponentialRampToValueAtTime(Math.max(40, f1), t + dur);
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(vol, t);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      src.connect(filter).connect(gain).connect(this.master);
      src.start(t, Math.random() * 0.2, dur + 0.05);
    }

    shoot() {
      if (!this.ctx || this.muted) return;
      const t = this.now();
      if (t - this.lastShot < 0.045) return;
      this.lastShot = t;
      this.tone({ type: 'square', f0: 880, f1: 420, dur: 0.06, vol: 0.035 });
      this.tone({ type: 'sine', f0: 1400, f1: 700, dur: 0.04, vol: 0.02 });
    }

    hit() {
      this.tone({ type: 'triangle', f0: 320, f1: 170, dur: 0.08, vol: 0.09 });
      this.burst({ dur: 0.08, vol: 0.1, f0: 2600, f1: 700 });
    }

    explode(big) {
      this.burst({ dur: big ? 0.55 : 0.26, vol: big ? 0.4 : 0.22, f0: big ? 1200 : 1900, f1: big ? 45 : 110 });
      this.tone({ type: 'sawtooth', f0: big ? 120 : 220, f1: 40, dur: big ? 0.5 : 0.22, vol: big ? 0.18 : 0.08 });
    }

    playerHit() {
      this.tone({ type: 'sawtooth', f0: 190, f1: 70, dur: 0.22, vol: 0.22 });
      this.burst({ dur: 0.2, vol: 0.2, f0: 900, f1: 180 });
    }

    pickup() {
      this.tone({ type: 'sine', f0: 660, f1: 660, dur: 0.09, vol: 0.13 });
      this.tone({ type: 'sine', f0: 990, f1: 990, dur: 0.14, vol: 0.12, delay: 0.07 });
      this.tone({ type: 'sine', f0: 1320, f1: 1320, dur: 0.16, vol: 0.09, delay: 0.14 });
    }

    dash() {
      this.burst({ dur: 0.24, vol: 0.18, f0: 500, f1: 3200, q: 2.2, type: 'bandpass' });
      this.tone({ type: 'sine', f0: 240, f1: 880, dur: 0.18, vol: 0.05 });
    }

    wave() {
      this.tone({ type: 'sine', f0: 330, f1: 330, dur: 0.5, vol: 0.09, attack: 0.05 });
      this.tone({ type: 'sine', f0: 494, f1: 494, dur: 0.5, vol: 0.07, delay: 0.08, attack: 0.05 });
      this.tone({ type: 'sine', f0: 660, f1: 660, dur: 0.55, vol: 0.06, delay: 0.16, attack: 0.05 });
    }

    boss() {
      this.tone({ type: 'sawtooth', f0: 70, f1: 55, dur: 1.1, vol: 0.18, attack: 0.2 });
      this.tone({ type: 'sawtooth', f0: 105, f1: 82, dur: 1.1, vol: 0.1, attack: 0.2 });
      this.burst({ dur: 0.8, vol: 0.18, f0: 300, f1: 60 });
    }

    gameOver() {
      this.tone({ type: 'sawtooth', f0: 220, f1: 55, dur: 1.2, vol: 0.16, attack: 0.02 });
      this.tone({ type: 'sine', f0: 110, f1: 40, dur: 1.4, vol: 0.12, delay: 0.1 });
      this.burst({ dur: 1.1, vol: 0.22, f0: 1400, f1: 50 });
    }

    ui() {
      this.tone({ type: 'sine', f0: 620, f1: 780, dur: 0.07, vol: 0.07 });
    }

    /* low ambient pad — starts with gameplay */
    startMusic() {
      if (!this.ctx || this.muted || this.musicNodes) return;
      const ctx = this.ctx;
      const gain = ctx.createGain();
      gain.gain.value = 0;
      gain.connect(this.master);
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 340;
      filter.Q.value = 3;
      filter.connect(gain);

      const oscs = [];
      [55, 82.5, 110, 164.8].forEach((freq, i) => {
        const osc = ctx.createOscillator();
        osc.type = i === 0 ? 'sine' : 'sawtooth';
        osc.frequency.value = freq;
        osc.detune.value = (i - 1.5) * 7;
        const g = ctx.createGain();
        g.gain.value = i === 0 ? 0.5 : 0.13;
        osc.connect(g).connect(filter);
        osc.start();
        oscs.push(osc);
      });

      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.value = 0.08;
      lfoGain.gain.value = 180;
      lfo.connect(lfoGain).connect(filter.frequency);
      lfo.start();

      gain.gain.setTargetAtTime(0.09, this.now(), 1.4);
      this.musicNodes = { gain, oscs, lfo };
      this.musicGain = gain;
    }

    stopMusic() {
      if (!this.musicNodes || !this.ctx) return;
      const { gain, oscs, lfo } = this.musicNodes;
      const t = this.now();
      gain.gain.cancelScheduledValues(t);
      gain.gain.setTargetAtTime(0, t, 0.25);
      oscs.forEach((o) => { try { o.stop(t + 1.2); } catch (e) { /* noop */ } });
      try { lfo.stop(t + 1.2); } catch (e) { /* noop */ }
      this.musicNodes = null;
    }
  }

  window.Sfx = Sfx;
})();

/* ============================================================
   GREEN ZONE — unified input (keyboard, mouse, gamepad, touch)
   ============================================================ */
(function () {
  'use strict';

  const DEAD = 0.18;
  const STICK_MAX = 54;

  const el = (id) => document.getElementById(id);

  function deadzone(x, y, dz) {
    const m = Math.hypot(x, y);
    if (m <= dz) return { x: 0, y: 0, m: 0 };
    const scale = Math.min(1, (m - dz) / (1 - dz)) / (m || 1);
    return { x: x * scale, y: y * scale, m: Math.hypot(x * scale, y * scale) };
  }

  class Input {
    constructor(canvas) {
      this.canvas = canvas;
      this.keys = new Set();
      this.move = { x: 0, y: 0 };
      this.aim = { x: 0, y: 0 };
      this.aimActive = false;
      this.pointer = { x: 0, y: 0, active: false, last: -Infinity };
      this.pad = { move: { x: 0, y: 0 }, aim: { x: 0, y: 0 }, aimActive: false };
      this.padConnected = false;
      this.padName = '';
      this.dashQueued = false;
      this.pauseQueued = false;
      this.pausedByVisibility = false;
      this.sticks = {
        left: { id: null, ox: 0, oy: 0, el: el('stickL'), knob: el('knobL') },
        right: { id: null, ox: 0, oy: 0, el: el('stickR'), knob: el('knobR') },
      };
      this.onGamepadChange = null;
      this.bind();
    }

    bind() {
      const canvas = this.canvas;

      window.addEventListener('keydown', (e) => {
        const k = e.key.toLowerCase();
        if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
        if (e.repeat) return;
        this.keys.add(k);
        if (k === ' ' || k === 'shift' || k === 'e') this.dashQueued = true;
        if (k === 'escape' || k === 'p') this.pauseQueued = true;
      }, { passive: false });

      window.addEventListener('keyup', (e) => {
        this.keys.delete(e.key.toLowerCase());
      });

      window.addEventListener('blur', () => {
        this.keys.clear();
        this.releaseSticks();
      });

      canvas.addEventListener('pointermove', (e) => {
        if (e.pointerType === 'touch') return;
        const r = canvas.getBoundingClientRect();
        this.pointer.x = e.clientX - r.left;
        this.pointer.y = e.clientY - r.top;
        this.pointer.active = true;
        this.pointer.last = performance.now();
      });

      canvas.addEventListener('pointerdown', (e) => {
        if (e.pointerType !== 'touch') {
          this.pointer.active = true;
          this.pointer.last = performance.now();
          const r = canvas.getBoundingClientRect();
          this.pointer.x = e.clientX - r.left;
          this.pointer.y = e.clientY - r.top;
          return;
        }
        e.preventDefault();
        document.body.classList.add('is-touch');
        const side = e.clientX < window.innerWidth * 0.5 ? 'left' : 'right';
        const stick = this.sticks[side];
        if (stick.id !== null) return;
        stick.id = e.pointerId;
        stick.ox = e.clientX;
        stick.oy = e.clientY;
        if (stick.el) {
          stick.el.style.left = e.clientX + 'px';
          stick.el.style.top = e.clientY + 'px';
          stick.el.classList.add('is-active');
        }
        if (stick.knob) stick.knob.style.transform = 'translate(0px, 0px)';
        this.setStick(side, 0, 0);
        try { canvas.setPointerCapture(e.pointerId); } catch (err) { /* noop */ }
      }, { passive: false });

      canvas.addEventListener('pointermove', (e) => {
        if (e.pointerType !== 'touch') return;
        const side = this.sticks.left.id === e.pointerId ? 'left' : this.sticks.right.id === e.pointerId ? 'right' : null;
        if (!side) return;
        const stick = this.sticks[side];
        let dx = e.clientX - stick.ox;
        let dy = e.clientY - stick.oy;
        const m = Math.hypot(dx, dy);
        if (m > STICK_MAX) {
          dx = (dx / m) * STICK_MAX;
          dy = (dy / m) * STICK_MAX;
        }
        if (stick.knob) stick.knob.style.transform = `translate(${dx}px, ${dy}px)`;
        const nx = dx / STICK_MAX;
        const ny = dy / STICK_MAX;
        const dz = deadzone(nx, ny, 0.14);
        this.setStick(side, dz.x, dz.y);
      }, { passive: true });

      const endTouch = (e) => {
        const side = this.sticks.left.id === e.pointerId ? 'left' : this.sticks.right.id === e.pointerId ? 'right' : null;
        if (side) this.releaseStick(side);
      };
      canvas.addEventListener('pointerup', endTouch);
      canvas.addEventListener('pointercancel', endTouch);
      canvas.addEventListener('lostpointercapture', endTouch);
      canvas.addEventListener('contextmenu', (e) => e.preventDefault());

      window.addEventListener('gamepadconnected', (e) => {
        this.padConnected = true;
        this.padName = e.gamepad.id;
        if (this.onGamepadChange) this.onGamepadChange(true, e.gamepad.id);
      });
      window.addEventListener('gamepaddisconnected', () => {
        this.padConnected = false;
        if (this.onGamepadChange) this.onGamepadChange(false, '');
      });

      const kick = () => {
        if (this.onFirstGesture) this.onFirstGesture();
      };
      window.addEventListener('pointerdown', kick, { once: false });
      window.addEventListener('keydown', kick, { once: false });
    }

    setStick(side, x, y) {
      if (side === 'left') {
        this.move.x = x;
        this.move.y = y;
      } else {
        this.aim.x = x;
        this.aim.y = y;
        this.aimActive = Math.hypot(x, y) > 0.001;
      }
    }

    releaseStick(side) {
      const stick = this.sticks[side];
      stick.id = null;
      if (stick.el) stick.el.classList.remove('is-active');
      if (stick.knob) stick.knob.style.transform = 'translate(0px, 0px)';
      this.setStick(side, 0, 0);
    }

    releaseSticks() {
      this.releaseStick('left');
      this.releaseStick('right');
    }

    queueDash() { this.dashQueued = true; }
    queuePause() { this.pauseQueued = true; }
    takeDash() { const v = this.dashQueued; this.dashQueued = false; return v; }
    takePause() { const v = this.pauseQueued; this.pauseQueued = false; return v; }

    keyVector() {
      let x = 0;
      let y = 0;
      const k = this.keys;
      if (k.has('a') || k.has('arrowleft')) x -= 1;
      if (k.has('d') || k.has('arrowright')) x += 1;
      if (k.has('w') || k.has('arrowup')) y -= 1;
      if (k.has('s') || k.has('arrowdown')) y += 1;
      const m = Math.hypot(x, y);
      return m > 0 ? { x: x / m, y: y / m } : { x: 0, y: 0 };
    }

    pollGamepad(now) {
      const pads = navigator.getGamepads ? navigator.getGamepads() : [];
      let pad = null;
      for (const p of pads) { if (p && p.connected) { pad = p; break; } }
      if (!pad) {
        this.pad.move.x = this.pad.move.y = 0;
        this.pad.aim.x = this.pad.aim.y = 0;
        this.pad.aimActive = false;
        this.padConnected = false;
        return;
      }
      this.padConnected = true;
      this.padName = pad.id;

      let mx = pad.axes[0] || 0;
      let my = pad.axes[1] || 0;
      // D-pad fallback
      if (pad.buttons[12] && pad.buttons[12].pressed) my = -1;
      if (pad.buttons[13] && pad.buttons[13].pressed) my = 1;
      if (pad.buttons[14] && pad.buttons[14].pressed) mx = -1;
      if (pad.buttons[15] && pad.buttons[15].pressed) mx = 1;
      const md = deadzone(mx, my, DEAD);
      this.pad.move.x = md.x;
      this.pad.move.y = md.y;

      const ax = pad.axes[2] || 0;
      const ay = pad.axes[3] || 0;
      const ad = deadzone(ax, ay, 0.3);
      this.pad.aim.x = ad.x;
      this.pad.aim.y = ad.y;
      this.pad.aimActive = Math.hypot(ad.x, ad.y) > 0.01;

      const btn = (i) => pad.buttons[i] && pad.buttons[i].pressed;
      if (btn(0) && !this._prevA) this.dashQueued = true;
      if ((btn(9) || btn(8)) && !this._prevStart) this.pauseQueued = true;
      this._prevA = btn(0);
      this._prevStart = btn(9) || btn(8);
    }

    /**
     * Combined input snapshot. Aim is a direction vector when the player
     * is actively steering it; otherwise the game auto-aims.
     */
    sample(now) {
      this.pollGamepad(now);

      let mv = this.keyVector();
      if (this.pad.move.x || this.pad.move.y) mv = this.pad.move;

      const rx = this.aimActive ? this.aim : { x: 0, y: 0 };
      const p = this.pad.aimActive ? this.pad.aim : { x: 0, y: 0 };
      const ax = this.aimActive ? rx.x : p.x;
      const ay = this.aimActive ? rx.y : p.y;

      if (now - this.pointer.last > 3500) this.pointer.active = false;

      return {
        moveX: mv.x,
        moveY: mv.y,
        aimX: ax,
        aimY: ay,
        aimActive: Math.hypot(ax, ay) > 0.01,
        pointer: this.pointer,
        dash: this.takeDash(),
        pause: this.takePause(),
      };
    }

    reset() {
      this.keys.clear();
      this.releaseSticks();
      this.dashQueued = false;
      this.pauseQueued = false;
    }
  }

  window.Input = Input;
})();

