drawBullets() {
  const ctx = this.ctx;
  if (!this.bullets.length) return;
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round';
  ctx.beginPath();
  for (const b of this.bullets) {
    ctx.moveTo(b.x - Math.cos(b.a) * 14, b.y - Math.sin(b.a) * 14);
    ctx.lineTo(b.x, b.y);
  }
  ctx.strokeStyle = 'rgba(155, 240, 11, 0.2)';
  ctx.lineWidth = 9;
  ctx.stroke();
  ctx.strokeStyle = '#eaffc0';
  ctx.lineWidth = 2.4;
  ctx.stroke();
  ctx.lineCap = 'butt';
  ctx.globalCompositeOperation = 'source-over';
}

drawEnemyBullets() {
  const ctx = this.ctx;
  if (!this.ebullets.length) return;
  const groups = {};
  for (const b of this.ebullets) {
    (groups[b.color] || (groups[b.color] = [])).push(b);
  }
  ctx.globalCompositeOperation = 'lighter';
  for (const color in groups) {
    const arr = groups[color];
    ctx.beginPath();
    for (const b of arr) {
      ctx.moveTo(b.x + b.r * 2.1, b.y);
      ctx.arc(b.x, b.y, b.r * 2.1, 0, TAU);
    }
    ctx.fillStyle = hexA(color, 0.13);
    ctx.fill();
    ctx.beginPath();
    for (const b of arr) {
      ctx.moveTo(b.x + b.r, b.y);
      ctx.arc(b.x, b.y, b.r, 0, TAU);
    }
    ctx.fillStyle = hexA(color, 0.85);
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';
  ctx.beginPath();
  for (const b of this.ebullets) {
    ctx.moveTo(b.x + 2, b.y);
    ctx.arc(b.x, b.y, 2, 0, TAU);
  }
  ctx.fillStyle = '#fff4f6';
  ctx.fill();
}

