Use eval overrides and measure each (1s). Let's do it efficiently in a single eval returning a series with helper that measures rAF fps. One eval can run multiple async measurements and mutate functions.

```js
async () => {
 const g=window.__gz.game;
 const fps=()=>new Promise(res=>{let n=0;const t0=performance.now();const f=()=>{n++;if(performance.now()-t0<900)requestAnimationFrame(f);else res(Math.round(n/0.9));};requestAnimationFrame(f);});
 const out={baseline:await fps()};
 g._dp=g.drawParticles; g.drawParticles=()=>{}; out.noParticles=await fps();
 g._de=g.drawEnemies; g.drawEnemies=()=>{}; out.noEnemies=await fps();
 g._dpl=g.drawPlayer; g.drawPlayer=()=>{}; out.noPlayer=await fps();
 g._dbu=g.drawBullets; g.drawBullets=()=>{}; out.noBullets=await fps();
 g._deb=g.drawEnemyBullets; g.drawEnemyBullets=()=>{}; out.noEBullets=await fps();
 g._dpi=g.drawPickups; g.drawPickups=()=>{}; out.noPickups=await fps();
 g._dr=g.drawRings; g.drawRings=()=>{}; g._dt=g.drawTexts; g.drawTexts=()=>{}; out.noRingsTexts=await fps();
 g.drawBackground=g._db||g.drawBackground; // no-op? 
 return out;
}
```
